<script lang="ts">
 import {onMount,onDestroy} from 'svelte';
 import {companyTurnPath,projectCompanyEvent,readCompanyEvents,turnFinished,verifiedCompanyTurn,type CompanyTurn,type TurnProjection} from '$lib/utils/company-turn';
 import {createEventDispatcher} from 'svelte';
 export let turn:CompanyTurn;export let accessSignal:AbortSignal;
 const dispatch=createEventDispatcher();const startedActive=['QUEUED','RUNNING'].includes(turn.status);const seenBrowserCursors=new Set<number>();let state:TurnProjection={cursor:0,status:turn.status,tools:[]};let stopping=false;let error='',expanded=false,elapsed=0,streamText='';const controller=new AbortController();let mounted=false,timer:ReturnType<typeof setInterval>,started=Date.now();
 $: active=['QUEUED','RUNNING'].includes(state.status);
 $: label=state.status==='RUNNING'?'Working':state.status==='QUEUED'?'Queued':state.status==='ANSWERED'?'Completed':state.status==='CANCELLED'?'Stopped':state.status==='FAILED'?'Could not finish':'Outcome unconfirmed';
 async function get(path:string,token:string,method='GET'){const r=await fetch(path,{method,headers:{Authorization:'Bearer '+token,Accept:path.endsWith('/events')?'text/event-stream':'application/json','Last-Event-ID':String(state.cursor)},credentials:'same-origin',cache:'no-store',signal:controller.signal});if(token!==localStorage.token||controller.signal.aborted||accessSignal.aborted)throw Error('Session changed');if([401,403,404].includes(r.status)){dispatch('denied',{status:r.status});halt();throw Error('Activity access changed');}if(!r.ok)throw Error('Live activity unavailable');return r;}
 async function follow(){const token=localStorage.token,base=companyTurnPath(turn);let failures=0;while(mounted&&!controller.signal.aborted){try{const r=await get(base+'/events',token);await readCompanyEvents(r,controller.signal,event=>{if(token!==localStorage.token||controller.signal.aborted||accessSignal.aborted)return;const next=projectCompanyEvent(turn,state,event);if(next===state)return;state=next;error='';
 if(event.type==='text.delta'&&typeof event.text==='string'){
  if(streamText.length+event.text.length<=250000){
   streamText+=event.text;
   dispatch('content',{runId:turn.runId,assistantMessageId:turn.assistantMessageId,text:streamText});
  }
 }else{
  if((startedActive||active)&&event.type==='tool.lifecycle'&&typeof event.publicToolName==='string'&&event.publicToolName.startsWith('browser.')&&!seenBrowserCursors.has(next.cursor)){
   seenBrowserCursors.add(next.cursor);
   dispatch('browser',{companyId:turn.companyId,conversationId:turn.conversationId,botId:turn.botId,runId:turn.runId,toolName:event.publicToolName,status:event.status});
  }
  dispatch('refresh');
 }
 dispatch('state',{...turn,status:state.status});});if(controller.signal.aborted)return;const fresh=await(await get(base,token)).json();if(controller.signal.aborted||accessSignal.aborted||token!==localStorage.token||!mounted)return;if(!verifiedCompanyTurn(fresh,turn.companyId,turn.conversationId,turn.assistantMessageId))throw Error('Activity scope changed');state={...state,status:fresh.status};dispatch('state',fresh);dispatch('refresh');failures=0;if(turnFinished(state.status))return;}catch{if(controller.signal.aborted)return;if(++failures>=4){error='Live activity disconnected. Refresh to reconnect.';return;}}await new Promise<void>(resolve=>{const t=setTimeout(resolve,Math.min(500*2**failures,5000));controller.signal.addEventListener('abort',()=>{clearTimeout(t);resolve();},{once:true});});}}
 async function stopThisRun(){if(stopping||!active||accessSignal.aborted||controller.signal.aborted)return;const target={...turn},token=localStorage.token;stopping=true;error='';try{const response=await get(companyTurnPath(target)+'/cancel',token,'POST');const result=await response.json();if(controller.signal.aborted||accessSignal.aborted||token!==localStorage.token||!mounted)return;const verified=verifiedCompanyTurn(result,target.companyId,target.conversationId,target.assistantMessageId);if(!verified||verified.runId!==target.runId||verified.botId!==target.botId)throw Error('Stop receipt scope changed');state={...state,status:verified.status};dispatch('state',verified);dispatch('refresh');}catch{if(!controller.signal.aborted&&!accessSignal.aborted)error='Stop could not be confirmed for this bot. Refresh its status before retrying.';}finally{stopping=false;}}
 function halt(){controller.abort();streamText='';state={cursor:0,status:'',tools:[]};error='';}
 onMount(()=>{mounted=true;accessSignal.addEventListener('abort',halt,{once:true});if(accessSignal.aborted){halt();return;}timer=setInterval(()=>{if(active)elapsed=Math.floor((Date.now()-started)/1000);},1000);void follow();return()=>accessSignal.removeEventListener('abort',halt);});onDestroy(()=>{mounted=false;controller.abort();clearInterval(timer);});
</script>
<div class="activity" data-run={turn.runId}><div class="activity-header"><button class="summary" aria-expanded={expanded} on:click={()=>expanded=!expanded}><span class:spin={active} class="indicator">{active?'':state.status==='ANSWERED'?'✓':'·'}</span><span>{label}</span>{#if active}<span class="elapsed">{elapsed}s</span>{/if}<span class="chevron">{expanded?'⌃':'⌄'}</span></button>{#if active}<button class="stop-one" type="button" aria-label="Stop only this bot’s current run" disabled={stopping} on:click={stopThisRun}>{stopping?'Stopping…':'Stop this bot'}</button>{/if}</div>{#if expanded}<div class="details">{#each state.tools as tool(tool.id)}<div><span class:spin={tool.status==='RUNNING'} class="indicator">{tool.status==='COMPLETED'?'✓':''}</span><span>{tool.name}</span><small>{tool.status.toLowerCase()}</small></div>{:else}<p>{active?'Waiting for runtime activity.':'No tool activity recorded.'}</p>{/each}</div>{/if}{#if error}<p role="status">{error}</p>{/if}</div>
<style>.activity{font-size:12px;color:#767b86;margin:12px 0}.summary{display:flex;align-items:center;gap:8px;min-height:28px;background:none;border:0;color:inherit;cursor:pointer}.indicator{width:13px;height:13px;display:inline-flex;align-items:center;justify-content:center;font-size:11px;flex:none}.spin{border:1.5px solid #d7dbe3;border-top-color:#7b8da9;border-radius:50%;animation:rotate 1s linear infinite}.elapsed{color:#a3a7ae}.chevron{margin-left:7px}.details{padding:8px 0 3px 20px}.details>div{display:flex;align-items:center;gap:8px;padding:6px 0}.details small{margin-left:auto}.details p{margin:0}p{font-size:12px}@keyframes rotate{to{transform:rotate(360deg)}}@media(prefers-reduced-motion:reduce){.spin{animation:none}}.activity{color:#71809a}.summary{color:#516887}.spin{border-color:#e4ebf8;border-top-color:#3466f6}.details{border-left:1px solid #e6ebf4;margin-left:6px;padding-left:14px}.details small{font-size:10px;color:#8190a8}
.activity-header{display:flex;align-items:center;gap:12px;flex-wrap:wrap}.stop-one{border:1px solid #efc4cd;border-radius:6px;background:#fff;color:#b4233a;font:inherit;font-size:10px;padding:4px 8px;cursor:pointer}.stop-one:hover:not(:disabled){background:#fff1f3}.stop-one:disabled{opacity:.5;cursor:default}.stop-one:focus-visible{outline:2px solid #2563eb;outline-offset:3px}
</style>
